python3 << 'EOF'
import json, urllib.request, urllib.error

def post(payload, raw=False):
    body = payload if raw else json.dumps(payload).encode()
    req = urllib.request.Request(
        "http://127.0.0.1:5000/sentiment",
        data=body if isinstance(body, bytes) else body.encode(),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req) as r:
            return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e:
        return e.code, json.loads(e.read())

tests = [
    ("positive", {"text": "This movie was absolutely wonderful and I loved every minute of it!"}),
    ("negative", {"text": "This is the worst product I have ever bought. Terrible quality, total waste of money."}),
    ("missing text", {"foo": "bar"}),
    ("non-string text", {"text": 12345}),
    ("non-dict body", ["hello"]),
]
for name, payload in tests:
    status, resp = post(payload)
    print(f"--- {name}: HTTP {status} -> {json.dumps(resp)}")
EOF
